1	package com.example.starter.gas.service;
2	
3	import com.example.starter.gas.ApiException;
4	import com.example.starter.gas.domain.AssessmentRow;
5	import com.example.starter.gas.domain.MeterReadingRow;
6	import com.example.starter.gas.domain.VoucherRow;
7	import com.example.starter.gas.dto.AdjustmentRequest;
8	import com.example.starter.gas.dto.AssessmentResponse;
9	import com.example.starter.gas.dto.ConfirmRequest;
10	import com.example.starter.gas.dto.DisputeRequest;
11	import com.example.starter.gas.dto.ReadingSubmitRequest;
12	import com.example.starter.gas.dto.ReadingSubmitResponse;
13	import com.example.starter.gas.dto.SealRequest;
14	import com.example.starter.gas.dto.VoucherCreateRequest;
15	import com.example.starter.gas.dto.VoucherResponse;
16	import com.example.starter.gas.repo.AssessmentRepository;
17	import com.example.starter.gas.repo.IdempotencyRepository;
18	import com.example.starter.gas.repo.MeterReadingRepository;
19	import com.example.starter.gas.repo.ReferenceDataRepository;
20	import com.example.starter.gas.repo.VoucherRepository;
21	import com.fasterxml.jackson.databind.ObjectMapper;
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.dao.DuplicateKeyException;
25	import org.springframework.stereotype.Service;
26	import org.springframework.transaction.annotation.Transactional;
27	
28	import java.math.BigDecimal;
29	import java.time.Clock;
30	import java.time.LocalDate;
31	import java.time.ZoneOffset;
32	import java.util.List;
33	import java.util.concurrent.ThreadLocalRandom;
34	
35	/**
36	 * 天然气计量交接凭证与偏差考核主服务。
37	 *
38	 * <p>所有写操作以 requestId 幂等：指纹覆盖 requestId 与全部业务字段；
39	 * 同键同参返回首次结果，同键异参 409 且不产生新版本。</p>
40	 */
41	@Service
42	public class CustodyService {
43	
44	    private static final Logger log = LoggerFactory.getLogger(CustodyService.class);
45	
46	    /** 争议期长度：生效后 7 个自然日（UTC），恰第 7 日仍可发起争议。 */
47	    static final int DISPUTE_WINDOW_DAYS = 7;
48	
49	    private static final String TYPE_READING = "READING";
50	    private static final String TYPE_VOUCHER = "VOUCHER";
51	    private static final String TYPE_CONFIRM = "CONFIRM";
52	    private static final String TYPE_DISPUTE = "DISPUTE";
53	    private static final String TYPE_SEAL = "SEAL";
54	    private static final String TYPE_ADJUSTMENT = "ADJUSTMENT";
55	
56	    private final Clock clock;
57	    private final ObjectMapper objectMapper;
58	    private final ReferenceDataRepository referenceDataRepository;
59	    private final MeterReadingRepository meterReadingRepository;
60	    private final VoucherRepository voucherRepository;
61	    private final AssessmentRepository assessmentRepository;
62	    private final IdempotencyRepository idempotencyRepository;
63	    private final TerminalSealer terminalSealer;
64	
65	    public CustodyService(Clock clock,
66	                          ObjectMapper objectMapper,
67	                          ReferenceDataRepository referenceDataRepository,
68	                          MeterReadingRepository meterReadingRepository,
69	                          VoucherRepository voucherRepository,
70	                          AssessmentRepository assessmentRepository,
71	                          IdempotencyRepository idempotencyRepository,
72	                          TerminalSealer terminalSealer) {
73	        this.clock = clock;
74	        this.objectMapper = objectMapper;
75	        this.referenceDataRepository = referenceDataRepository;
76	        this.meterReadingRepository = meterReadingRepository;
77	        this.voucherRepository = voucherRepository;
78	        this.assessmentRepository = assessmentRepository;
79	        this.idempotencyRepository = idempotencyRepository;
80	        this.terminalSealer = terminalSealer;
81	    }
82	
83	    /**
84	     * 提交计量读数：按“站＋表底时刻”去重，乱序按 UTC 日界归位；
85	     * 若该站日凭证已生成，后到读数记差异记录，不改已生成凭证。
86	     */
87	    @Transactional
88	    public ReadingSubmitResponse submitReading(ReadingSubmitRequest request) {
89	        String fingerprint = canonical(TYPE_READING, request.requestId(), request.stationCode(),
90	                request.meterTime(), request.volume().stripTrailingZeros().toPlainString(),
91	                request.heatingValue().stripTrailingZeros().toPlainString());
92	        return withIdempotency(TYPE_READING, request.requestId(), fingerprint,
93	                ReadingSubmitResponse.class, () -> doSubmitReading(request));
94	    }
95	
96	    private ReadingSubmitResponse doSubmitReading(ReadingSubmitRequest request) {
97	        requireStation(request.stationCode());
98	        LocalDate gasDate = LocalDate.ofInstant(request.meterTime(), ZoneOffset.UTC);
99	
100	        MeterReadingRow existing = meterReadingRepository.findByStationAndMeterTime(
101	                request.stationCode(), request.meterTime());
102	        if (existing != null) {
103	            // 同站同表底时刻天然同一读数：去重返回，不产生新版本
104	            return new ReadingSubmitResponse(existing.requestId(), existing.id(), existing.stationCode(),
105	                    existing.meterTime(), existing.gasDate(), existing.volume(),
106	                    existing.heatingValue(), true);
107	        }
108	
109	        long id;
110	        try {
111	            id = meterReadingRepository.insert(request.requestId(), request.stationCode(),
112	                    request.meterTime(), gasDate, request.volume(), request.heatingValue(),
113	                    clock.instant());
114	        } catch (DuplicateKeyException ex) {
115	            // 并发提交同表底时刻：重查去重
116	            MeterReadingRow raced = meterReadingRepository.findByStationAndMeterTime(
117	                    request.stationCode(), request.meterTime());
118	            if (raced != null) {
119	                return new ReadingSubmitResponse(raced.requestId(), raced.id(), raced.stationCode(),
120	                        raced.meterTime(), raced.gasDate(), raced.volume(),
121	                        raced.heatingValue(), true);
122	            }
123	            throw ApiException.conflict("READING_DUPLICATED", "读数已存在且内容不一致");
124	        }
125	
126	        // 凭证已先于本读数生成：迟到读数只入差异记录，不改凭证
127	        VoucherRow voucher = voucherRepository.findOriginalByStationAndDate(
128	                request.stationCode(), gasDate);
129	        if (voucher != null) {
130	            voucherRepository.insertReadingDiff(voucher.voucherNo(), id, request.stationCode(),
131	                    gasDate, request.volume(), request.heatingValue());
132	        }
133	
134	        return new ReadingSubmitResponse(request.requestId(), id, request.stationCode(),
135	                request.meterTime(), gasDate, request.volume(), request.heatingValue(), false);
136	    }
137	
138	    /**
139	     * 按气量日生成交接凭证：仅采用气量日 24:00（UTC）前已确认入库的读数；
140	     * 同站同气量日只允许一张有效原始凭证。
141	     */
142	    @Transactional
143	    public VoucherResponse createVoucher(VoucherCreateRequest request) {
144	        String fingerprint = canonical(TYPE_VOUCHER, request.requestId(),
145	                request.stationCode(), request.gasDate().toString());
146	        return withIdempotency(TYPE_VOUCHER, request.requestId(), fingerprint,
147	                VoucherResponse.class, () -> doCreateVoucher(request));
148	    }
149	
150	    private VoucherResponse doCreateVoucher(VoucherCreateRequest request) {
151	        requireStation(request.stationCode());
152	        LocalDate gasDate = request.gasDate();
153	
154	        String occupied = voucherRepository.findOccupiedVoucherNo(request.stationCode(), gasDate);
155	        if (occupied != null) {
156	            throw ApiException.conflict("VOUCHER_ALREADY_EXISTS",
157	                    "同站同气量日已存在有效凭证: " + occupied);
158	        }
159	
160	        java.time.Instant now = clock.instant();
161	        java.time.Instant dayEnd = gasDate.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();
162	        if (now.isBefore(dayEnd)) {
163	            throw ApiException.badRequest("GAS_DAY_NOT_CLOSED",
164	                    "气量日 " + gasDate + " 的 24:00（UTC）尚未到，不能生成凭证");
165	        }
166	
167	        List<MeterReadingRow> readings = meterReadingRepository.findConfirmedForDay(
168	                request.stationCode(), gasDate);
169	        if (readings.isEmpty()) {
170	            throw ApiException.badRequest("NO_CONFIRMED_READING",
171	                    "气量日 24:00（UTC）前没有已确认入库的读数，无法生成凭证");
172	        }
173	
174	        BigDecimal totalVolume = readings.stream()
175	                .map(MeterReadingRow::volume)
176	                .reduce(BigDecimal.ZERO, BigDecimal::add);
177	        BigDecimal weightedHv = GasCalculation.weightedHeatingValue(readings);
178	        BigDecimal energy = GasCalculation.energy(totalVolume, weightedHv);
179	        String voucherNo = newVoucherNo("V", request.stationCode(), gasDate);
180	
181	        try {
182	            // 数据库级占用，保证并发生成也只有一张
183	            voucherRepository.occupyStationDay(request.stationCode(), gasDate, voucherNo);
184	        } catch (DuplicateKeyException ex) {
185	            String raced = voucherRepository.findOccupiedVoucherNo(request.stationCode(), gasDate);
186	            throw ApiException.conflict("VOUCHER_ALREADY_EXISTS",
187	                    "同站同气量日已存在有效凭证: " + raced);
188	        }
189	        voucherRepository.insertOriginal(request.requestId(), voucherNo, request.stationCode(),
190	                gasDate, totalVolume, weightedHv, energy);
191	
192	        // 表底时刻归属本日、但 24:00（UTC）后才入库的迟到读数：记差异记录，不改已生成凭证
193	        for (MeterReadingRow late : meterReadingRepository.findLateReadings(
194	                request.stationCode(), gasDate)) {
195	            voucherRepository.insertReadingDiff(voucherNo, late.id(), request.stationCode(),
196	                    gasDate, late.volume(), late.heatingValue());
197	        }
198	
199	        return toVoucherResponse(voucherRepository.findByNo(voucherNo));
200	    }
201	
202	    /**
203	     * 交接方确认：双方须在同一事务语义下先后确认，凭证方为“生效”；
204	     * 单方确认仅为 PARTIALLY_CONFIRMED，不生效。
205	     */
206	    @Transactional
207	    public VoucherResponse confirm(String voucherNo, ConfirmRequest request) {
208	        String fingerprint = canonical(TYPE_CONFIRM, request.requestId(), voucherNo, request.party());
209	        return withIdempotency(TYPE_CONFIRM, request.requestId(), fingerprint,
210	                VoucherResponse.class, () -> doConfirm(voucherNo, request));
211	    }
212	
213	    private VoucherResponse doConfirm(String voucherNo, ConfirmRequest request) {
214	        VoucherRow voucher = requireVoucher(voucherNo);
215	        if (VoucherRow.TYPE_ADJUSTMENT.equals(voucher.voucherType())) {
216	            throw ApiException.conflict("ADJUSTMENT_NOT_CONFIRMABLE",
217	                    "调整凭证经双方签认提交即生效，无需再确认");
218	        }
219	        String status = voucher.status();
220	        if (VoucherRow.STATUS_SEALED.equals(status)) {
221	            throw ApiException.conflict("VOUCHER_SEALED", "凭证已封账，确认为终态后禁止操作");
222	        }
223	        if (VoucherRow.STATUS_DISPUTED.equals(status)) {
224	            throw ApiException.conflict("VOUCHER_DISPUTED", "凭证处于争议挂起状态，不能继续确认");
225	        }
226	        if (VoucherRow.STATUS_EFFECTIVE.equals(status)
227	                || voucherRepository.isConfirmedBy(voucherNo, request.party())) {
228	            // 重复确认（同方再次确认或凭证已生效）：返回当前状态，不产生新记录
229	            return toVoucherResponse(voucherRepository.findByNo(voucherNo));
230	        }
231	
232	        java.time.Instant now = clock.instant();
233	        voucherRepository.insertConfirmation(voucherNo, request.party(), request.requestId(), now);
234	        String otherParty = "A".equals(request.party()) ? "B" : "A";
235	        if (voucherRepository.isConfirmedBy(voucherNo, otherParty)) {
236	            // 双方确认齐备：同一事务内置为生效
237	            LocalDate effectiveDate = LocalDate.ofInstant(now, ZoneOffset.UTC);
238	            voucherRepository.markEffective(voucherNo, effectiveDate, now);
239	        } else {
240	            // 单方确认不生效
241	            voucherRepository.updateStatus(voucherNo,
242	                    VoucherRow.STATUS_PARTIALLY_CONFIRMED, request.party());
243	        }
244	        return toVoucherResponse(voucherRepository.findByNo(voucherNo));
245	    }
246	
247	    /**
248	     * 争议：凭证生效后进入 7 个自然日争议期（UTC 日界）；
249	     * 恰在第 7 日发起仍受理；逾期则封账为终态并拒绝争议。
250	     */
251	    @Transactional
252	    public VoucherResponse dispute(String voucherNo, DisputeRequest request) {
253	        String fingerprint = canonical(TYPE_DISPUTE, request.requestId(), voucherNo,
254	                request.party(), request.reason());
255	        return withIdempotency(TYPE_DISPUTE, request.requestId(), fingerprint,
256	                VoucherResponse.class, () -> doDispute(voucherNo, request));
257	    }
258	
259	    private VoucherResponse doDispute(String voucherNo, DisputeRequest request) {
260	        VoucherRow voucher = requireVoucher(voucherNo);
261	        if (voucher.effectiveDate() == null) {
262	            throw ApiException.badRequest("VOUCHER_NOT_EFFECTIVE", "凭证尚未生效，不能发起争议");
263	        }
264	        if (VoucherRow.STATUS_SEALED.equals(voucher.status())) {
265	            throw ApiException.conflict("VOUCHER_SEALED", "凭证已封账，争议一律拒绝");
266	        }
267	
268	        LocalDate today = LocalDate.ofInstant(clock.instant(), ZoneOffset.UTC);
269	        LocalDate lastDisputeDay = voucher.effectiveDate().plusDays(DISPUTE_WINDOW_DAYS);
270	        if (today.isAfter(lastDisputeDay)) {
271	            // 逾期：在独立事务中封账为终态（不随本次拒绝回滚），再拒绝争议
272	            terminalSealer.sealIfOpenInNewTransaction(voucherNo);
273	            throw ApiException.conflict("DISPUTE_WINDOW_CLOSED",
274	                    "争议期已于 " + lastDisputeDay + "（UTC）结束，凭证封账");
275	        }
276	
277	        if (VoucherRow.STATUS_DISPUTED.equals(voucher.status())) {
278	            // 争议已存在：返回挂起状态，唯一结果不重复落库
279	            return toVoucherResponse(voucherRepository.findByNo(voucherNo));
280	        }
281	
282	        java.time.Instant now = clock.instant();
283	        int updated = voucherRepository.markDisputedIfEffective(voucherNo);
284	        if (updated == 0) {
285	            // 并发：可能已被另一争议抢先或已封账
286	            VoucherRow latest = voucherRepository.findByNo(voucherNo);
287	            if (VoucherRow.STATUS_SEALED.equals(latest.status())) {
288	                throw ApiException.conflict("VOUCHER_SEALED", "凭证已封账，争议一律拒绝");
289	            }
290	            if (voucherRepository.disputeExists(voucherNo)) {
291	                return toVoucherResponse(latest);
292	            }
293	            throw ApiException.conflict("DISPUTE_REJECTED", "争议未能受理，请刷新凭证状态");
294	        }
295	        voucherRepository.insertDispute(voucherNo, request.requestId(),
296	                request.party(), request.reason(), now);
297	        return toVoucherResponse(voucherRepository.findByNo(voucherNo));
298	    }
299	
300	    /**
301	     * 封账为终态；重复封账幂等成功；争议期内拒绝封账；CAS 保证并发唯一结果。
302	     */
303	    @Transactional
304	    public VoucherResponse seal(String voucherNo, SealRequest request) {
305	        String fingerprint = canonical(TYPE_SEAL, request.requestId(), voucherNo);
306	        return withIdempotency(TYPE_SEAL, request.requestId(), fingerprint,
307	                VoucherResponse.class, () -> doSeal(voucherNo));
308	    }
309	
310	    private VoucherResponse doSeal(String voucherNo) {
311	        VoucherRow voucher = requireVoucher(voucherNo);
312	        if (VoucherRow.STATUS_SEALED.equals(voucher.status())) {
313	            // 重复封账：幂等成功
314	            return toVoucherResponse(voucher);
315	        }
316	        if (voucher.effectiveDate() == null) {
317	            throw ApiException.badRequest("VOUCHER_NOT_EFFECTIVE", "凭证尚未生效，不能封账");
318	        }
319	        LocalDate today = LocalDate.ofInstant(clock.instant(), ZoneOffset.UTC);
320	        LocalDate lastDisputeDay = voucher.effectiveDate().plusDays(DISPUTE_WINDOW_DAYS);
321	        if (!today.isAfter(lastDisputeDay)) {
322	            throw ApiException.conflict("SEAL_TOO_EARLY",
323	                    "争议期结束（" + lastDisputeDay + " UTC）前不能封账");
324	        }
325	        sealIfOpen(voucherNo);
326	        return toVoucherResponse(voucherRepository.findByNo(voucherNo));
327	    }
328	
329	    /** 条件封账：仅 EFFECTIVE/DISPUTED 可置为 SEALED。 */
330	    private void sealIfOpen(String voucherNo) {
331	        int updated = voucherRepository.sealIfOpen(voucherNo, clock.instant());
332	        if (updated == 0) {
333	            VoucherRow latest = voucherRepository.findByNo(voucherNo);
334	            if (!VoucherRow.STATUS_SEALED.equals(latest.status())) {
335	                throw ApiException.conflict("SEAL_REJECTED", "凭证当前状态不能封账: " + latest.status());
336	            }
337	        }
338	    }
339	
340	    /**
341	     * 封账后差错处理：双方签认的调整凭证引用原凭证号，提交即生效。
342	     */
343	    @Transactional
344	    public VoucherResponse adjust(String voucherNo, AdjustmentRequest request) {
345	        String fingerprint = canonical(TYPE_ADJUSTMENT, request.requestId(), voucherNo,
346	                request.volume().stripTrailingZeros().toPlainString(),
347	                request.heatingValue().stripTrailingZeros().toPlainString(),
348	                String.valueOf(request.signOffA()), String.valueOf(request.signOffB()));
349	        return withIdempotency(TYPE_ADJUSTMENT, request.requestId(), fingerprint,
350	                VoucherResponse.class, () -> doAdjust(voucherNo, request));
351	    }
352	
353	    private VoucherResponse doAdjust(String voucherNo, AdjustmentRequest request) {
354	        VoucherRow original = requireVoucher(voucherNo);
355	        if (VoucherRow.TYPE_ADJUSTMENT.equals(original.voucherType())) {
356	            throw ApiException.badRequest("ADJUSTMENT_OF_ADJUSTMENT", "不能对调整凭证再开调整凭证");
357	        }
358	        if (!VoucherRow.STATUS_SEALED.equals(original.status())) {
359	            throw ApiException.conflict("ORIGINAL_NOT_SEALED",
360	                    "原始凭证须封账后，差错方可经双方签认的调整凭证处理");
361	        }
362	        if (!Boolean.TRUE.equals(request.signOffA()) || !Boolean.TRUE.equals(request.signOffB())) {
363	            throw ApiException.badRequest("SIGN_OFF_REQUIRED", "调整凭证须经交接双方签认");
364	        }
365	        if (voucherRepository.findAdjustmentOf(voucherNo) != null) {
366	            throw ApiException.conflict("ADJUSTMENT_EXISTS", "该原始凭证已存在调整凭证");
367	        }
368	
369	        BigDecimal energy = GasCalculation.energy(request.volume(), request.heatingValue());
370	        String adjustmentNo = newVoucherNo("A", original.stationCode(), original.gasDate());
371	        try {
372	            voucherRepository.insertAdjustment(request.requestId(), adjustmentNo, voucherNo,
373	                    original.stationCode(), original.gasDate(), request.volume(),
374	                    request.heatingValue(), energy, clock.instant());
375	        } catch (DuplicateKeyException ex) {
376	            throw ApiException.conflict("ADJUSTMENT_EXISTS", "该原始凭证已存在调整凭证");
377	        }
378	        return toVoucherResponse(voucherRepository.findByNo(adjustmentNo));
379	    }
380	
381	    /** 查询凭证。 */
382	    public VoucherResponse getVoucher(String voucherNo) {
383	        return toVoucherResponse(requireVoucher(voucherNo));
384	    }
385	
386	    /**
387	     * 逐日复算偏差考核：实际能量取自最新有效凭证（调整凭证优先），
388	     * 偏差绝对值不超过日指定 3%（含）免考，超出部分×单价计违约金；结果稳定落库。
389	     */
390	    @Transactional
391	    public AssessmentResponse assessDay(String stationCode, LocalDate gasDate) {
392	        requireStation(stationCode);
393	        BigDecimal nominated = referenceDataRepository.findNomination(stationCode, gasDate);
394	        if (nominated == null) {
395	            throw ApiException.badRequest("NOMINATION_NOT_FOUND",
396	                    "缺少该气量日的日指定气量: " + gasDate);
397	        }
398	        BigDecimal unitPrice = referenceDataRepository.findPenaltyUnitPrice(stationCode);
399	        if (unitPrice == null) {
400	            throw ApiException.badRequest("CONTRACT_NOT_FOUND", "缺少管输合同约定单价");
401	        }
402	
403	        VoucherRow original = voucherRepository.findOriginalByStationAndDate(stationCode, gasDate);
404	        if (original == null) {
405	            throw ApiException.badRequest("VOUCHER_NOT_FOUND", "该气量日尚无凭证，无法考核");
406	        }
407	        VoucherRow basis = voucherRepository.findAdjustmentOf(original.voucherNo());
408	        if (basis == null) {
409	            basis = original;
410	        }
411	        if (basis.effectiveDate() == null) {
412	            throw ApiException.conflict("VOUCHER_NOT_EFFECTIVE", "凭证尚未经双方确认生效，暂不考核");
413	        }
414	
415	        BigDecimal deviation = GasCalculation.deviation(basis.energy(), nominated);
416	        BigDecimal deviationAbs = deviation.abs();
417	        BigDecimal tolerance = GasCalculation.toleranceEnergy(nominated);
418	        boolean exempt = deviationAbs.compareTo(tolerance) <= 0;
419	        BigDecimal penalty = GasCalculation.penalty(deviationAbs, tolerance, unitPrice);
420	
421	        AssessmentRow row = new AssessmentRow(stationCode, gasDate, basis.voucherNo(),
422	                nominated.setScale(2), basis.energy(), deviation, deviationAbs,
423	                tolerance, exempt, penalty);
424	        assessmentRepository.upsert(row);
425	        return toAssessmentResponse(row);
426	    }
427	
428	    /** 查询某站已复算落库的考核明细（按气量日升序，结果稳定）。 */
429	    public List<AssessmentResponse> listAssessments(String stationCode) {
430	        requireStation(stationCode);
431	        return assessmentRepository.findByStation(stationCode).stream()
432	                .map(CustodyService::toAssessmentResponse)
433	                .toList();
434	    }
435	
436	    // ------------------------------------------------------------------
437	    // 辅助方法
438	    // ------------------------------------------------------------------
439	
440	    private void requireStation(String stationCode) {
441	        if (!referenceDataRepository.stationExists(stationCode)) {
442	            throw ApiException.notFound("STATION_NOT_FOUND", "交接站不存在: " + stationCode);
443	        }
444	    }
445	
446	    private VoucherRow requireVoucher(String voucherNo) {
447	        VoucherRow voucher = voucherRepository.findByNo(voucherNo);
448	        if (voucher == null) {
449	            throw ApiException.notFound("VOUCHER_NOT_FOUND", "凭证不存在: " + voucherNo);
450	        }
451	        return voucher;
452	    }
453	
454	    private String newVoucherNo(String prefix, String stationCode, LocalDate gasDate) {
455	        return prefix + "-" + stationCode + "-" + gasDate + "-"
456	                + Integer.toHexString(ThreadLocalRandom.current().nextInt(0x100000, 0xFFFFFF));
457	    }
458	
459	    /**
460	     * 幂等包装：同键同参返回首次响应快照；同键异参 409；并发同键落败者重查裁决。
461	     */
462	    private <T> T withIdempotency(String requestType, String requestId, String fingerprint,
463	                                  Class<T> responseType, java.util.function.Supplier<T> action) {
464	        String existingFingerprint = idempotencyRepository.findFingerprint(requestId);
465	        if (existingFingerprint != null) {
466	            if (!existingFingerprint.equals(fingerprint)) {
467	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
468	                        "相同 requestId 提交了不同的业务参数");
469	            }
470	            return readSnapshot(requestId, responseType);
471	        }
472	
473	        T result = action.get();
474	        String snapshot;
475	        try {
476	            snapshot = objectMapper.writeValueAsString(result);
477	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
478	            throw new IllegalStateException("幂等响应快照序列化失败", ex);
479	        }
480	        try {
481	            idempotencyRepository.insert(requestId, requestType, fingerprint, snapshot);
482	        } catch (DuplicateKeyException ex) {
483	            // 并发同键：以先提交者的指纹/快照为准
484	            String racedFingerprint = idempotencyRepository.findFingerprint(requestId);
485	            if (racedFingerprint == null) {
486	                throw ApiException.conflict("IDEMPOTENCY_RACE", "幂等并发冲突，请稍后重试");
487	            }
488	            if (!racedFingerprint.equals(fingerprint)) {
489	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
490	                        "相同 requestId 提交了不同的业务参数");
491	            }
492	            return readSnapshot(requestId, responseType);
493	        }
494	        return result;
495	    }
496	
497	    private <T> T readSnapshot(String requestId, Class<T> responseType) {
498	        String json = idempotencyRepository.findResponse(requestId);
499	        try {
500	            return objectMapper.readValue(json, responseType);
501	        } catch (Exception ex) {
502	            log.warn("幂等响应快照反序列化失败 requestId={}", requestId, ex);
503	            throw ApiException.badRequest("IDEMPOTENCY_SNAPSHOT_INVALID", "首次响应快照不可读");
504	        }
505	    }
506	
507	    private static String canonical(Object... parts) {
508	        return String.join("|", java.util.Arrays.stream(parts).map(String::valueOf).toList());
509	    }
510	
511	    static VoucherResponse toVoucherResponse(VoucherRow row) {
512	        return new VoucherResponse(row.voucherNo(), row.requestId(), row.voucherType(),
513	                row.originalVoucherNo(), row.stationCode(), row.gasDate(), row.volume(),
514	                row.weightedHeatingValue(), row.energy(), row.status(), row.firstConfirmParty(),
515	                row.effectiveDate(), row.effectiveAt(), row.sealedAt());
516	    }
517	
518	    static AssessmentResponse toAssessmentResponse(AssessmentRow row) {
519	        return new AssessmentResponse(row.stationCode(), row.gasDate(), row.voucherNo(),
520	                row.nominatedEnergy(), row.actualEnergy(), row.deviation(), row.deviationAbs(),
521	                row.toleranceEnergy(), row.exempt(), row.penalty());
522	    }
523	}
