59	    /** 查询同站同气量日的原始凭证（同日唯一约束）。 */
60	    public VoucherRow findOriginalByStationAndDate(String stationCode, LocalDate gasDate) {
61	        List<VoucherRow> rows = jdbc.query(
62	                "SELECT * FROM custody_voucher WHERE station_code = ? AND gas_date = ? "
63	                        + "AND voucher_type = 'ORIGINAL' ORDER BY id LIMIT 1",
64	                ROW_MAPPER, stationCode, java.sql.Date.valueOf(gasDate));
