69	    public String insertOriginal(String requestId, String voucherNo, String stationCode, LocalDate gasDate,
70	                                 BigDecimal volume, BigDecimal weightedHv, BigDecimal energy) {
71	        jdbc.update(
72	                "INSERT INTO custody_voucher (voucher_no, request_id, voucher_type, station_code, gas_date, "
73	                        + "volume, weighted_heating_value, energy, status) "
74	                        + "VALUES (?, ?, 'ORIGINAL', ?, ?, ?, ?, ?, 'DRAFT')",
75	                voucherNo, requestId, stationCode, java.sql.Date.valueOf(gasDate),
76	                volume, weightedHv, energy);
77	        return voucherNo;
78	    }
79	
80	    /** 插入调整凭证（双方签认，提交即生效）。 */
81	    public String insertAdjustment(String requestId, String voucherNo, String originalVoucherNo,
82	                                   String stationCode, LocalDate gasDate,
83	                                   BigDecimal volume, BigDecimal weightedHv,
84	                                   BigDecimal energy, Instant now) {
85	        jdbc.update(
86	                "INSERT INTO custody_voucher (voucher_no, request_id, voucher_type, original_voucher_no, "
87	                        + "station_code, gas_date, volume, weighted_heating_value, energy, status, "
88	                        + "effective_date, effective_at) "
89	                        + "VALUES (?, ?, 'ADJUSTMENT', ?, ?, ?, ?, ?, ?, 'EFFECTIVE', ?, ?)",
90	                voucherNo, requestId, originalVoucherNo, stationCode, java.sql.Date.valueOf(gasDate),
91	                volume, weightedHv, energy, java.sql.Date.valueOf(LocalDate.ofInstant(now, java.time.ZoneOffset.UTC)),
92	                Timestamp.from(now));
93	        return voucherNo;
94	    }
95	
96	    /**
97	     * 插入确认记录；唯一约束冲突返回 false，由调用方按重复确认/幂等处理。
98	     */
99	    public boolean insertConfirmation(String voucherNo, String party, String requestId, Instant now) {
100	        try {
101	            jdbc.update(
102	                    "INSERT INTO voucher_confirmation (voucher_no, party, request_id, confirmed_at) "
103	                            + "VALUES (?, ?, ?, ?)",
104	                    voucherNo, party, requestId, Timestamp.from(now));
105	            return true;
106	        } catch (DuplicateKeyException ex) {
107	            return false;
108	        }
109	    }
110	
111	    /** 某方是否已确认。 */
112	    public boolean isConfirmedBy(String voucherNo, String party) {
113	        Integer count = jdbc.queryForObject(
114	                "SELECT COUNT(1) FROM voucher_confirmation WHERE voucher_no = ? AND party = ?",
115	                Integer.class, voucherNo, party);
116	        return count != null && count > 0;
117	    }
118	
119	    /** 更新凭证状态（单方确认时记录首个确认方）。 */
120	    public void updateStatus(String voucherNo, String status, String firstConfirmParty) {
121	        jdbc.update(
122	                "UPDATE custody_voucher SET status = ?, first_confirm_party = COALESCE(first_confirm_party, ?), "
123	                        + "updated_at = CURRENT_TIMESTAMP WHERE voucher_no = ?",
124	                status, firstConfirmParty, voucherNo);
125	    }
126	
127	    /** 双方确认齐备，置为生效。 */
128	    public void markEffective(String voucherNo, LocalDate effectiveDate, Instant effectiveAt) {
129	        jdbc.update(
130	                "UPDATE custody_voucher SET status = 'EFFECTIVE', effective_date = ?, effective_at = ?, "
131	                        + "updated_at = CURRENT_TIMESTAMP WHERE voucher_no = ?",
132	                java.sql.Date.valueOf(effectiveDate), Timestamp.from(effectiveAt), voucherNo);
133	    }
134	
135	    /** 置为争议挂起。 */
136	    public void markDisputed(String voucherNo) {
137	        jdbc.update(
138	                "UPDATE custody_voucher SET status = 'DISPUTED', updated_at = CURRENT_TIMESTAMP WHERE voucher_no = ?",
139	                voucherNo);
140	    }
141	
142	    /**
143	     * 条件置争议：仅当状态为 EFFECTIVE 时更新为 DISPUTED，返回受影响行数；
144	     * 用于并发封账/争议的唯一结果裁决。
145	     */
146	    public int markDisputedIfEffective(String voucherNo) {
147	        return jdbc.update(
148	                "UPDATE custody_voucher SET status = 'DISPUTED', updated_at = CURRENT_TIMESTAMP "
149	                        + "WHERE voucher_no = ? AND status = 'EFFECTIVE'",
150	                voucherNo);
151	    }
152	
153	    /** 封账终态。 */
154	    public void markSealed(String voucherNo, Instant sealedAt) {
155	        jdbc.update(
156	                "UPDATE custody_voucher SET status = 'SEALED', sealed_at = ?, updated_at = CURRENT_TIMESTAMP "
157	                        + "WHERE voucher_no = ?",
158	                Timestamp.from(sealedAt), voucherNo);
159	    }
160	
161	    /**
162	     * 条件封账：仅当状态仍为 EFFECTIVE/DISPUTED 时更新为 SEALED，
163	     * 返回受影响行数；用于并发封账/争议的唯一结果裁决。
164	     */
165	    public int sealIfOpen(String voucherNo, Instant sealedAt) {
166	        return jdbc.update(
167	                "UPDATE custody_voucher SET status = 'SEALED', sealed_at = ?, updated_at = CURRENT_TIMESTAMP "
168	                        + "WHERE voucher_no = ? AND status IN ('EFFECTIVE', 'DISPUTED')",
169	                Timestamp.from(sealedAt), voucherNo);
170	    }
171	
172	    /** 插入争议；已有争议或键冲突返回 false。 */
173	    public boolean insertDispute(String voucherNo, String requestId, String party, String reason, Instant now) {
174	        try {
175	            jdbc.update(
176	                    "INSERT INTO voucher_dispute (voucher_no, request_id, party, reason, created_at) "
177	                            + "VALUES (?, ?, ?, ?, ?)",
178	                    voucherNo, requestId, party, reason, Timestamp.from(now));
179	            return true;
180	        } catch (DuplicateKeyException ex) {
181	            return false;
182	        }
183	    }
184	
185	    /** 是否存在有效争议。 */
186	    public boolean disputeExists(String voucherNo) {
187	        Integer count = jdbc.queryForObject(
188	                "SELECT COUNT(1) FROM voucher_dispute WHERE voucher_no = ?", Integer.class, voucherNo);
189	        return count != null && count > 0;
190	    }
191	
192	    /** 插入迟到读数差异记录。 */
