16	
17	import java.time.Instant;
18	import java.time.LocalDate;
19	import java.util.Map;
20	
21	import static org.assertj.core.api.Assertions.assertThat;
22	
23	/**
24	 * 经真实 HTTP 入口（随机端口）验证主流程与错误语义（201/200/409/400）。
25	 */
26	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
27	@Import(TestClockConfiguration.class)
28	class GasCustodyHttpTest {
29	
30	    @LocalServerPort
31	    private int port;
32	    @Autowired
33	    private TestRestTemplate restTemplate;
34	    @Autowired
35	    private JdbcTemplate jdbc;
36	    @Autowired
37	    private MutableClock clock;
38	
39	    private String url(String path) {
40	        return "http://localhost:" + port + path;
41	    }
42	
43	    @BeforeEach
44	    void setUp() {
45	        DatabaseFixtures.reset(jdbc);
46	        DatabaseFixtures.addNomination(jdbc, LocalDate.of(2026, 9, 20), "380000.00");
47	    }
48	
49	    @Test
50	    void httpFlow_readingVoucherConfirmAssess_andConflictSemantics() {
51	        clock.setInstant(Instant.parse("2026-09-20T12:00:00Z"));
52	        Map<String, Object> reading = Map.of(
53	                "requestId", "http-r1",
54	                "stationCode", "ST01",
55	                "meterTime", "2026-09-20T12:00:00Z",
56	                "volume", "10000",
57	                "heatingValue", "39.200000");
58	        ResponseEntity<Map> readingResp = restTemplate.postForEntity(
59	                url("/api/readings"), reading, Map.class);
60	        assertThat(readingResp.getStatusCode()).isEqualTo(HttpStatus.CREATED);
61	        assertThat(readingResp.getBody()).containsEntry("duplicated", false);
62	        assertThat(readingResp.getBody()).containsEntry("gasDate", "2026-09-20");
63	
64	        // 同站同表底时刻以另一 requestId 提交：去重 duplicated=true
65	        Map<String, Object> readingDup = Map.of(
66	                "requestId", "http-r2",
67	                "stationCode", "ST01",
68	                "meterTime", "2026-09-20T12:00:00Z",
69	                "volume", "10000",
70	                "heatingValue", "39.200000");
71	        ResponseEntity<Map> dupResp = restTemplate.postForEntity(
72	                url("/api/readings"), readingDup, Map.class);
73	        assertThat(dupResp.getStatusCode()).isEqualTo(HttpStatus.CREATED);
74	        assertThat(dupResp.getBody()).containsEntry("duplicated", true);
75	
76	        // 气量日未结束生成凭证：400
77	        Map<String, Object> voucherReq = Map.of(
78	                "requestId", "http-v1", "stationCode", "ST01",
79	                "gasDate", "2026-09-20");
80	        ResponseEntity<Map> early = restTemplate.postForEntity(
81	                url("/api/vouchers"), voucherReq, Map.class);
82	        assertThat(early.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
83	        assertThat(early.getBody()).containsEntry("code", "GAS_DAY_NOT_CLOSED");
84	
85	        // 24:00 后生成凭证：201
86	        clock.setInstant(Instant.parse("2026-09-21T00:10:00Z"));
87	        ResponseEntity<Map> voucherResp = restTemplate.postForEntity(
88	                url("/api/vouchers"), voucherReq, Map.class);
89	        assertThat(voucherResp.getStatusCode()).isEqualTo(HttpStatus.CREATED);
90	        assertThat(voucherResp.getBody()).containsEntry("status", "DRAFT");
91	        assertThat(voucherResp.getBody()).containsEntry("energy", 392000.00);
92	        String voucherNo = (String) voucherResp.getBody().get("voucherNo");
93	
94	        // 同站同日再生成：409
95	        Map<String, Object> voucherReq2 = Map.of(
96	                "requestId", "http-v2", "stationCode", "ST01",
97	                "gasDate", "2026-09-20");
98	        ResponseEntity<Map> conflict = restTemplate.postForEntity(
99	                url("/api/vouchers"), voucherReq2, Map.class);
100	        assertThat(conflict.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
101	        assertThat(conflict.getBody()).containsEntry("code", "VOUCHER_ALREADY_EXISTS");
102	
103	        // 双方确认
104	        ResponseEntity<Map> aResp = restTemplate.postForEntity(
105	                url("/api/vouchers/" + voucherNo + "/confirmations"),
106	                Map.of("requestId", "http-c1", "party", "A"), Map.class);
107	        assertThat(aResp.getStatusCode()).isEqualTo(HttpStatus.OK);
108	        assertThat(aResp.getBody()).containsEntry("status", "PARTIALLY_CONFIRMED");
109	        ResponseEntity<Map> bResp = restTemplate.postForEntity(
110	                url("/api/vouchers/" + voucherNo + "/confirmations"),
111	                Map.of("requestId", "http-c2", "party", "B"), Map.class);
112	        assertThat(bResp.getStatusCode()).isEqualTo(HttpStatus.OK);
